1	import { useMutation, useQuery } from "@tanstack/react-query";
2	import { useRoute } from "wouter";
3	import { TRADES_THEME as T } from "@/lib/trades-theme";
4	
5	const money = (cents: number) => new Intl.NumberFormat("en-NZ", { style: "currency", currency: "NZD" }).format(cents / 100);
6	
7	export default function QuoteResponse() {
8	  const [, params] = useRoute("/trades/quote/:token");
9	  const token = params?.token || "";
10	  const { data, isLoading, error } = useQuery<any>({
11	    queryKey: ["/api/trades/quotes/token", token],
12	    queryFn: () => fetch(`/api/trades/quotes/token/${token}`).then(async r => { if (!r.ok) throw new Error((await r.json()).message || "Quote not found"); return r.json(); }),
13	    enabled: !!token,
14	  });
15	  const respond = useMutation({
16	    mutationFn: async (accept: boolean) => {
17	      const response = await fetch(`/api/trades/quotes/token/${token}/respond`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ accept }) });
18	      if (!response.ok) throw new Error(await response.json().then(d => d.message).catch(() => "Could not respond"));
19	      return response.json();
20	    },
21	  });
22	
23	  if (isLoading) return <Frame><p>Loading quote...</p></Frame>;
24	  if (error || !data) return <Frame><h1>Quote unavailable</h1><p>{(error as Error)?.message}</p></Frame>;
